String computeEtag(String json) throws NoSuchAlgorithmException {
    byte[] hash = MessageDigest.getInstance("SHA-256").digest(json.getBytes());
    return "\"" + HexFormat.of().formatHex(hash, 0, 8) + "\""; // pierwsze 8 bajtow jako hex
}

